import 'package:flutter/material.dart';
import '../../services/product_service.dart';
class SellerDashboard extends StatelessWidget { const SellerDashboard({super.key}); @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Seller Dashboard')),floatingActionButton:FloatingActionButton(onPressed:()=>showDialog(context:c,builder:(_)=>const AddProductDialog()),child:const Icon(Icons.add)),body:StreamBuilder(stream:ProductService().myProducts(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator()); final list=s.data!;return ListView.builder(itemCount:list.length,itemBuilder:(c,i)=>ListTile(title:Text(list[i].title),subtitle:Text('${list[i].price} AFN'),trailing:Text(list[i].approved?'Approved':'Pending'));}));}
}
class AddProductDialog extends StatefulWidget{const AddProductDialog({super.key});@override State<AddProductDialog> createState()=>_AddProductDialogState();}
class _AddProductDialogState extends State<AddProductDialog>{final t=TextEditingController(),d=TextEditingController(),p=TextEditingController(),s=TextEditingController(),city=TextEditingController(),cat=TextEditingController();bool loading=false;
Future<void> save()async{setState(()=>loading=true);try{await ProductService().addProduct(title:t.text,description:d.text,price:double.tryParse(p.text)??0,stock:int.tryParse(s.text)??-1,city:city.text,categoryId:cat.text);if(mounted)Navigator.pop(context);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}finally{if(mounted)setState(()=>loading=false);}}
@override Widget build(BuildContext c)=>AlertDialog(title:const Text('نوی محصول'),content:SingleChildScrollView(child:Column(children:[TextField(controller:t,decoration:const InputDecoration(labelText:'نوم')),TextField(controller:d,decoration:const InputDecoration(labelText:'Description')),TextField(controller:p,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'قیمت AFN')),TextField(controller:s,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Stock')),TextField(controller:city,decoration:const InputDecoration(labelText:'ښار')),TextField(controller:cat,decoration:const InputDecoration(labelText:'Category ID'))])),actions:[TextButton(onPressed:loading?null:()=>Navigator.pop(context),child:const Text('لغوه')),FilledButton(onPressed:loading?null:save,child:const Text('Save'))]);}
